import urllib.request, xml.etree.ElementTree as ET, email.utils, datetime, re, json
feeds = {
    'CoinDesk':'https://www.coindesk.com/arc/outboundfeeds/rss/',
    'CoinTelegraph':'https://cointelegraph.com/rss',
    'Decrypt':'https://decrypt.co/feed',
    'GoogleNews':'https://news.google.com/rss/search?q=bitcoin+crypto&hl=en-US&gl=US&ceid=US:en',
}
now = datetime.datetime.now(datetime.timezone.utc)
cutoff = now - datetime.timedelta(hours=24)
all_items=[]
for src,url in feeds.items():
    try:
        data = urllib.request.urlopen(url, timeout=15).read()
    except Exception as e:
        print(src, 'FETCH_ERR', e)
        continue
    root = ET.fromstring(data)
    # RSS or Atom
    items=[]
    if root.tag.endswith('rss'):
        ch = root.find('channel')
        items = ch.findall('item') if ch is not None else []
    else:
        ns = {'a':'http://www.w3.org/2005/Atom'}
        items = root.findall('a:entry', ns)
    for it in items[:30]:
        if it.tag.endswith('entry'):
            title = (it.findtext('{http://www.w3.org/2005/Atom}title') or '').strip()
            link_el = it.find('{http://www.w3.org/2005/Atom}link')
            link = link_el.attrib.get('href') if link_el is not None else ''
            pub = (it.findtext('{http://www.w3.org/2005/Atom}updated') or it.findtext('{http://www.w3.org/2005/Atom}published') or '').strip()
            desc = (it.findtext('{http://www.w3.org/2005/Atom}summary') or '').strip()
        else:
            title = (it.findtext('title') or '').strip()
            link = (it.findtext('link') or '').strip()
            pub = (it.findtext('pubDate') or '').strip()
            desc = (it.findtext('description') or '').strip()
        dt = None
        try:
            dt = email.utils.parsedate_to_datetime(pub)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            pass
        if dt and dt < cutoff:
            continue
        all_items.append({'source':src,'title':title,'link':link,'pubDate':pub,'desc':re.sub(r'\s+',' ',desc)[:240]})

print(json.dumps(all_items[:120], indent=2))
PY
